#include <stdio.h>
#include <string.h>
#include "sheen/network-tv.h"
int main(int argc,char **argv){if(argc<3){fprintf(stderr,"usage: %s CATALOG list | validate | open CHANNEL_ID\n",argv[0]);return 2;}sheen_network_catalog c;int rc=sheen_network_catalog_load(argv[1],&c);if(rc){fprintf(stderr,"catalog load failed: %d\n",rc);return 1;}if(!strcmp(argv[2],"list")){printf("{\"count\":%zu,\"channels\":[",c.count);for(size_t i=0;i<c.count;i++){if(i)putchar(',');printf("{\"channel_id\":\"%s\",\"name\":\"%s\",\"uri\":\"%s\",\"enabled\":%s}",c.channels[i].channel_id,c.channels[i].name,c.channels[i].uri,c.channels[i].enabled?"true":"false");}puts("]}");return 0;}if(!strcmp(argv[2],"open")&&argc==4){sheen_network_channel x;if(sheen_network_catalog_get(&c,argv[3],&x))return 1;sheen_live_session *s=sheen_network_open(&x);if(!s)return 1;if(sheen_live_play(s))return 1;unsigned char b[188];ssize_t n=sheen_live_read(s,b,sizeof(b));printf("{\"channel_id\":\"%s\",\"first_read_bytes\":%lld}\n",x.channel_id,(long long)n);sheen_live_close(s);return n>0?0:1;}fprintf(stderr,"invalid command\n");return 2;}
